import re

def node_by_title(doc, title):
    for node in doc["nodes"]:
        if node["title"] == title:
            return node
    return None

def scope_nodes(doc, scope):
    node = node_by_title(doc, scope)
    if not node:
        return []
    return [node_by_id(doc, nid) for nid in node.get("children", [])]

def node_by_id(doc, node_id):
    for node in doc["nodes"]:
        if node["node_id"] == node_id:
            return node
    return None

def table_rows(node):
    if node["kind"] != "table":
        return []
    cols = node["table"]["columns"]
    rows = node["table"]["rows"]
    return [(i, {cols[j]: row[j] for j in range(len(cols))}) for i, row in enumerate(rows)]

def entities(doc, scope) -> list:
    prod_node = node_by_title(doc, f"{scope}: Products")
    if not prod_node:
        return []
    rows = table_rows(prod_node)
    return [{"id": row[1]["product"], "description": row[1]["product"]} for row in rows]

def recorded_end(doc, scope) -> float or None:
    text_node = node_by_title(doc, scope)
    if not text_node:
        return None
    match = re.search(r"Days \d+ to (\d+)", text_node["text"])
    if match:
        return float(match.group(1))
    return None

def inputs(doc, scope) -> list:
    inputs_list = []
    input_id_counter = 0

    # Start day for opening stock
    text_node = node_by_title(doc, scope)
    start_day = None
    if text_node:
        match = re.search(r"Days (\d+) to \d+", text_node["text"])
        if match:
            start_day = float(match.group(1))

    # 1. Opening Stock
    prod_node = node_by_title(doc, f"{scope}: Products")
    if prod_node:
        for row_idx, row in table_rows(prod_node):
            inputs_list.append({
                "id": f"in_{input_id_counter}",
                "time": start_day,
                "kind": "opening_stock",
                "entities": [row["product"]],
                "fields": {"opening_stock": int(row["opening stock"])},
                "src": [prod_node["node_id"], row_idx]
            })
            input_id_counter += 1

    # 2. Daily Production and Orders
    ledger_node = node_by_title(doc, f"{scope}: Daily ledger")
    if ledger_node:
        for row_idx, row in table_rows(ledger_node):
            day = float(row["day"])
            prod = row["product"]
            # Produced
            if int(row["produced"]) > 0:
                inputs_list.append({
                    "id": f"in_{input_id_counter}",
                    "time": day,
                    "kind": "production",
                    "entities": [prod],
                    "fields": {"produced": int(row["produced"])},
                    "src": [ledger_node["node_id"], row_idx]
                })
                input_id_counter += 1
            # Ordered
            if int(row["ordered"]) > 0:
                inputs_list.append({
                    "id": f"in_{input_id_counter}",
                    "time": day,
                    "kind": "order",
                    "entities": [prod],
                    "fields": {"ordered": int(row["ordered"])},
                    "src": [ledger_node["node_id"], row_idx]
                })
                input_id_counter += 1

    # 3. Order Book - Future Production and Orders
    nodes = scope_nodes(doc, scope)
    for node in nodes:
        if node["kind"] == "table" and "Orders received and production planned" in node["title"]:
            for row_idx, row in table_rows(node):
                day = float(row["day"])
                prod = row["product"]
                # Planned Production
                if int(row["planned production"]) > 0:
                    inputs_list.append({
                        "id": f"in_{input_id_counter}",
                        "time": day,
                        "kind": "planned_production",
                        "entities": [prod],
                        "fields": {"planned_production": int(row["planned production"])},
                        "src": [node["node_id"], row_idx]
                    })
                    input_id_counter += 1
                # Ordered
                if int(row["ordered"]) > 0:
                    inputs_list.append({
                        "id": f"in_{input_id_counter}",
                        "time": day,
                        "kind": "planned_order",
                        "entities": [prod],
                        "fields": {"ordered": int(row["ordered"])},
                        "src": [node["node_id"], row_idx]
                    })
                    input_id_counter += 1

    return inputs_list

