                elif "backlog is cleared" in line: kind = "backlog_cleared"

                outcomes_list.append({
                    "time": day,
                    "kind": kind,
                    "entities": entities_list,
                    "value": None,
                    "src": [events_node["node_id"], line_idx]
                })

    # 3. Order Book - Open orders at end (backordered)
    nodes = scope_nodes(doc, scope)
    for node in nodes:
        if node["kind"] == "table" and "Open orders at the end of day" in node["title"]:
            for row_idx, row in table_rows(node):
                # This describes the state at the end of the period
                # Time is the end day of the period
                end_day = recorded_end(doc, scope)
                outcomes_list.append({
                    "time": end_day,
                    "kind": "open_order_end",
                    "entities": [row["product"]],
                    "value": int(row["units still open"]),
                    "src": [node["node_id"], row_idx]
                })

    return outcomes_list

